const trackAbortListeners = signal => {
	let count = 0;
	const proxy = new Proxy(signal, {
		get(target, prop) {
			if (prop === 'addEventListener') {
				return (type, listener, ...rest) => {
					if (type === 'abort') {
						count++;
					}

					return target.addEventListener(type, listener, ...rest);
				};
			}

			if (prop === 'removeEventListener') {
				return (type, listener, ...rest) => {
					if (type === 'abort') {
						count--;
					}

					return target.removeEventListener(type, listener, ...rest);
				};
			}

			return Reflect.get(target, prop);
		},
	});

	return {
		proxy,
		get count() {
			return count;
		},
	};
};

