test('abort-listener-queue-state-machine', async t => {
	const controller = new AbortController();
	const tracker = trackAbortListeners(controller.signal);

	t.is(tracker.count, 0, 'initial idle');

	const limit = pLimit({concurrency: 2, signal: tracker.proxy});

	// Fill concurrency so subsequent tasks actually stay queued
	const running1 = limit(async () => delay(200));
	const running2 = limit(async () => delay(200));
	await delay(10);
	t.is(tracker.count, 0, 'running only, no listener');

	// Queued → listener attached
	const queued1 = limit(async () => delay(100));
	t.is(tracker.count, 1, 'queue 0→1');

	// ClearQueue → listener detached
	queued1.catch(() => {}); // eslint-disable-line promise/prefer-await-to-then
	limit.clearQueue();
	t.is(tracker.count, 0, 'after clearQueue');

	// Queued again → listener attached
	const queued2 = limit(async () => delay(100));
	t.is(tracker.count, 1, 'queue 0→1 again');

	// Abort → listener self-removes
	queued2.catch(() => {}); // eslint-disable-line promise/prefer-await-to-then
	controller.abort(new Error('x'));
	t.is(tracker.count, 0, 'after abort self-removes');

	// Natural drain: wait for running tasks to finish, then queue a new task
	await Promise.all([running1, running2]);
	await delay(10);

	// Fill concurrency again (signal is aborted, so these immediately reject)
	// Use a fresh controller for the drain test
	const controller2 = new AbortController();
	const tracker2 = trackAbortListeners(controller2.signal);
	const limit2 = pLimit({concurrency: 1, signal: tracker2.proxy});

	t.is(tracker2.count, 0, 'fresh limiter, initial idle');

	const running3 = limit2(async () => delay(200));
	await delay(10);
	t.is(tracker2.count, 0, 'running only');

	const queued3 = limit2(async () => delay(100));
	t.is(tracker2.count, 1, 'queue 0→1');

	// Let it drain naturally
	await delay(400);
	t.is(tracker2.count, 0, 'natural drain 1→0');
	await running3;
	await queued3;
});

